--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Mathf = CS.UnityEngine.Mathf
local Vector3 = CS.UnityEngine.Vector3
local Input = CS.UnityEngine.Input
local KeyCode = CS.UnityEngine.KeyCode
local Time = CS.UnityEngine.Time

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local IdolLive3D_Utils = import('Game.IdolLive3D.IdolLive3D_Utils')

---@type IdolLive3D_States
local IdolLive3D_States = import('Game.IdolLive3D.IdolLive3D_States')

---@type Live3D_CustomEvents
local Live3D_CustomEvents = import('Game.IdolLive3D.Interactive.Customs.Live3D_CustomEvents')

-- ========================================================





-- ========================================================


function Live3D_14900850:__init(  )
    --printError("Live3D_14900850 init")
end


-- 需手动调用 Delete()
function Live3D_14900850:__delete()
    --printError("Live3D_14900850 delete")
end


function Live3D_14900850:OnDestroy()
    --printError("   ~~~~~~~ Live3D_14900850 : OnDestroy() ~~~~~~~")
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    IdolLive3D_Utils.StopCoroutine(self.co_1)
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- ====================================================== 

-- 在 mainForRuntime Init() 尾部被调用
function Live3D_14900850:OnMainInitEnd( mainForRuntime_ ) 
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    self.mainForRuntime = mainForRuntime_
    self.uiMain = mainForRuntime_.uiMain  -- Env
    self.uiMainTF = self.uiMain.controller.gameObject.transform
    self.baseJson = mainForRuntime_.baseJson
    ---
    self.clothSceneNodes = self.mainForRuntime.idolLive3D_FreeNodesMgr:FindNodes("c_", "cloth")
    self:ShowCloths(false)


    self.uiCustomGO = self.mainForRuntime.allResources.prefabGOs["ui"] -- 定制 ui
    IdolLive3D_Utils.SetUIParent( self.uiCustomGO.transform, self.uiMainTF )
    CfUtils.SetActive( self.uiCustomGO, true )
    self.uiCustomEnv = CfUtils.GetLuaScr(self.uiCustomGO, "Game.IdolLive3D.Interactive.Customs.UI_14900850")
    self.uiCustomEnv:Init(self.mainForRuntime)
    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [Live3D_CustomEvents.Init_StartTwoIdlesChoose] = Bind(self, self.Init_StartTwoIdlesChoose),
        [Live3D_CustomEvents.Init_IntoIdle100]  = Bind(self, self.Init_IntoIdle100),
        [Live3D_CustomEvents.Init_IntoIdle200]  = Bind(self, self.Init_IntoIdle200),
        [Live3D_CustomEvents.DoDress]           = Bind(self, self.ShowCloths),
    })
end



function Live3D_14900850:Update() 
    self.uiCustomEnv:SelfUpdate()
end


function Live3D_14900850:Init_StartTwoIdlesChoose( idle100CB_, idle200CB_ ) 
    self.uiCustomEnv:ShowPanel_1(true)
    self.uiCustomEnv:ShowPanel_2(false)
    self.uiCustomEnv:BindCB_ChooseIdle100( idle100CB_ )
    self.uiCustomEnv:BindCB_ChooseIdle200( idle200CB_ )
end



function Live3D_14900850:Init_IntoIdle100() 
    -- 延迟出现: 
    IdolLive3D_Utils.StopCoroutine(self.co_1)
    self.co_1 = cs_coroutine.start(function()
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 ))
        self.uiCustomEnv:ShowPanel_1(false)
        self.uiCustomEnv:ShowPanel_2(true)
    end)
end



function Live3D_14900850:Init_IntoIdle200() 
end


function Live3D_14900850:ShowCloths( isShow_ ) 
    for _,node in pairs(self.clothSceneNodes) do 
        CfUtils.SetActive( node.transform.gameObject, isShow_ )
    end 
end





return Live3D_14900850
